<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exchange Rates</title><link rel="stylesheet" href="/assets/css/legacy-style.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="card card-wide"><h1>Exchange Rates</h1><?php foreach (($errors ?? []) as $error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endforeach; ?><form method="post" action="/exchange-rates"><input type="hidden" name="_token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><label>Currency Code</label><input name="currency_code" placeholder="USD" required><label>Rate to NAD</label><input name="rate_to_nad" type="number" min="0.000001" step="0.000001" required><label>Effective Date</label><input name="effective_date" type="date" value="<?= date('Y-m-d') ?>" required><button type="submit">Add Rate</button></form><table class="table"><thead><tr><th>ID</th><th>Currency</th><th>Rate</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php if (($rows ?? []) === []): ?><tr><td colspan="5">No exchange rates yet.</td></tr><?php else: foreach ($rows as $r): ?><tr><td><?= (int) $r['rate_id'] ?></td><td><?= htmlspecialchars($r['currency_code'], ENT_QUOTES, 'UTF-8') ?></td><td><?= number_format((float) $r['rate_to_nad'], 6) ?></td><td><?= htmlspecialchars($r['effective_date'], ENT_QUOTES, 'UTF-8') ?></td><td><form method="post" action="/exchange-rates/delete" class="inline-form" onsubmit="return confirm('Delete this rate?');"><input type="hidden" name="_token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="rate_id" value="<?= (int) $r['rate_id'] ?>"><button type="submit">Delete</button></form></td></tr><?php endforeach; endif; ?></tbody></table><p><a href="/dashboard">Back to Dashboard</a></p></main></body></html>
